import XCTest
@testable import FaceforgeCore

/// Golden fixtures generated by tools/make_fixtures.py from the Python
/// reference (which matches insightface 0.7.3 exactly on real weights).
enum Fixtures {
    static let dir: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()   // FaceforgeCoreTests
        .deletingLastPathComponent()   // Tests
        .deletingLastPathComponent()   // FaceforgeCore
        .deletingLastPathComponent()   // ios
        .deletingLastPathComponent()   // repo root
        .appendingPathComponent("tests/fixtures")

    static func json(_ name: String) throws -> [String: Any] {
        let data = try Data(contentsOf: dir.appendingPathComponent(name))
        return try JSONSerialization.jsonObject(with: data) as! [String: Any]
    }

    static func hex(_ s: String) -> Data {
        var d = Data()
        var i = s.startIndex
        while i < s.endIndex {
            let j = s.index(i, offsetBy: 2)
            d.append(UInt8(s[i..<j], radix: 16)!)
            i = j
        }
        return d
    }
}

final class AlignmentTests: XCTestCase {
    func testMatchesPythonReference() throws {
        let f = try Fixtures.json("alignment.json")
        let cases = f["cases"] as! [[String: Any]]
        XCTAssertEqual(cases.count, 6)
        for c in cases {
            let kps = (c["kps"] as! [[Double]]).map { Point2(x: $0[0], y: $0[1]) }
            for (key, size) in [("M112", 112), ("M128", 128), ("M256", 256)] {
                let expected = c[key] as! [[Double]]
                let got = FaceAlign.estimateNorm(kps, size: size).rows
                for r in 0..<2 { for k in 0..<3 {
                    XCTAssertEqual(got[r][k], expected[r][k], accuracy: 1e-5, "\(key)[\(r)][\(k)]")
                } }
            }
        }
    }

    func testInverseRoundTrip() {
        let m = Affine2D(a: 1.3, b: -0.4, tx: 12, c: 0.4, d: 1.3, ty: -7)
        let p = Point2(x: 33, y: 71)
        let q = m.inverted.apply(m.apply(p))
        XCTAssertEqual(q.x, p.x, accuracy: 1e-9)
        XCTAssertEqual(q.y, p.y, accuracy: 1e-9)
    }

    func testTemplateMapsToItselfAt112() {
        let m = FaceAlign.estimateNorm(FaceAlign.arcfaceDst, size: 112)
        XCTAssertEqual(m.a, 1, accuracy: 1e-9); XCTAssertEqual(m.tx, 0, accuracy: 1e-6)
        let m128 = FaceAlign.estimateNorm(FaceAlign.arcfaceDst, size: 128)
        XCTAssertEqual(m128.tx, 8, accuracy: 1e-6)
    }
}

final class SCRFDTests: XCTestCase {
    func testDecodeMatchesPythonReference() throws {
        let f = try Fixtures.json("scrfd_decode.json")
        let outputs = (f["outputs"] as! [[Double]]).map { $0.map(Float.init) }
        let faces = SCRFD.decode(outputs: outputs, inputSize: f["input_size"] as! Int,
                                 threshold: Float(f["threshold"] as! Double),
                                 nmsThreshold: Float(f["nms_threshold"] as! Double),
                                 detScale: Float(f["det_scale"] as! Double))
        let expected = f["expected"] as! [[String: Any]]
        XCTAssertEqual(faces.count, expected.count)
        for (got, exp) in zip(faces, expected) {
            XCTAssertEqual(got.score, Float(exp["score"] as! Double), accuracy: 1e-5)
            let eb = exp["bbox"] as! [Double]
            for i in 0..<4 { XCTAssertEqual(Double(got.bbox[i]), eb[i], accuracy: 2e-3) }
            let ek = exp["kps"] as! [[Double]]
            for i in 0..<5 {
                XCTAssertEqual(got.kps[i].x, ek[i][0], accuracy: 2e-3)
                XCTAssertEqual(got.kps[i].y, ek[i][1], accuracy: 2e-3)
            }
        }
    }

    func testLetterbox() {
        let l = SCRFD.letterbox(frameWidth: 720, frameHeight: 1280, size: 320)
        XCTAssertEqual(l.width, 180); XCTAssertEqual(l.height, 320)
        XCTAssertEqual(l.scale, 0.25, accuracy: 1e-6)
        let w = SCRFD.letterbox(frameWidth: 1280, frameHeight: 720, size: 320)
        XCTAssertEqual(w.width, 320); XCTAssertEqual(w.height, 180)
    }
}

final class OnnxReaderTests: XCTestCase {
    func testReadsLastInitializer() throws {
        let meta = try Fixtures.json("onnx_initializer.json")
        let t = try OnnxInitializerReader.lastInitializer(
            fileURL: Fixtures.dir.appendingPathComponent(meta["file"] as! String))
        XCTAssertEqual(t.name, meta["name"] as! String)
        XCTAssertEqual(t.dims, meta["dims"] as! [Int])
        let expected = (meta["values"] as! [Double]).map(Float.init)
        XCTAssertEqual(t.floats.count, expected.count)
        for (a, b) in zip(t.floats, expected) { XCTAssertEqual(a, b, accuracy: 1e-6) }
    }

    func testTruncatedFileThrows() throws {
        let meta = try Fixtures.json("onnx_initializer.json")
        let data = try Data(contentsOf: Fixtures.dir.appendingPathComponent(meta["file"] as! String))
        XCTAssertThrowsError(try OnnxInitializerReader.lastInitializer(data: data.prefix(data.count / 2)))
    }
}

final class ProtocolTests: XCTestCase {
    func testEncodingMatchesPython() throws {
        let f = try Fixtures.json("protocol_v1.json")
        let hello = f["hello"] as! [String: Any]
        XCTAssertEqual(OffloadProtocol.encodeJSON(.hello, hello["json"] as! [String: Any]),
                       Fixtures.hex(hello["hex"] as! String))
        let fr = f["frame"] as! [String: Any]
        XCTAssertEqual(OffloadProtocol.frame(id: UInt32(fr["frame_id"] as! Int),
                                             clientTimeUS: UInt64(fr["client_time_us"] as! Int),
                                             jpeg: Fixtures.hex(fr["jpeg_hex"] as! String)),
                       Fixtures.hex(fr["hex"] as! String))
        let err = f["error"] as! [String: Any]
        XCTAssertEqual(OffloadProtocol.encodeJSON(.error, err["json"] as! [String: Any]),
                       Fixtures.hex(err["hex"] as! String))
    }

    func testDecodesPythonResultInChunks() throws {
        let f = try Fixtures.json("protocol_v1.json")
        let r = f["result"] as! [String: Any]
        let bytes = Fixtures.hex(r["hex"] as! String)
        var dec = OffloadProtocol.Decoder()
        var msgs: [OffloadProtocol.Message] = []
        for i in stride(from: 0, to: bytes.count, by: 5) {     // arrive in small pieces
            msgs += try dec.feed(bytes.subdata(in: i..<min(i + 5, bytes.count)))
        }
        XCTAssertEqual(msgs.count, 1)
        XCTAssertEqual(msgs[0].type, .result)
        let res = try OffloadProtocol.parseResult(msgs[0].payload)
        XCTAssertEqual(res.frameID, 7)
        XCTAssertEqual(res.clientTimeUS, 1234567890123)
        XCTAssertEqual(res.serverMs, 12.5)
        XCTAssertTrue(res.faceFound)
        XCTAssertEqual(res.jpeg, Fixtures.hex(r["jpeg_hex"] as! String))
    }

    func testRejectsBadMagic() {
        var dec = OffloadProtocol.Decoder()
        XCTAssertThrowsError(try dec.feed(Data("XXXX00000000".utf8)))
    }
}

final class TensorAndStatsTests: XCTestCase {
    func testBGRAToCHWAndBack() {
        // 2x1 image: pixel0 B=10 G=20 R=30, pixel1 B=255 G=128 R=0
        let px: [UInt8] = [10, 20, 30, 255, 255, 128, 0, 255]
        let t = px.withUnsafeBufferPointer {
            Tensor.chwRGB(fromBGRA: $0.baseAddress!, width: 2, height: 1, rowBytes: 8, mean: 0, std: 255)
        }
        XCTAssertEqual(t[0], 30 / 255, accuracy: 1e-6)    // R plane
        XCTAssertEqual(t[3], 128 / 255, accuracy: 1e-6)   // G plane, pixel 1
        XCTAssertEqual(t[4], 10 / 255, accuracy: 1e-6)    // B plane
        let back = Tensor.bgra(fromCHWRGB: t, width: 2, height: 1)
        XCTAssertEqual(Array(back[0..<3]), [10, 20, 30])
        XCTAssertEqual(back[3], 255)
    }

    func testInswapperLatentIsUnitLength() {
        let emb: [Float] = [3, 4]
        let emap: [Float] = [1, 0, 0, 2]   // 2x2
        let lat = Tensor.inswapperLatent(embedding: emb, emap: emap)
        XCTAssertEqual(lat[0] * lat[0] + lat[1] * lat[1], 1, accuracy: 1e-6)
        XCTAssertEqual(lat[1] / lat[0], (0.8 * 2) / 0.6, accuracy: 1e-5)
    }

    func testOnePercentLow() {
        var s = FrameStats()
        for _ in 0..<99 { s.add(ms: 10) }
        s.add(ms: 100)
        XCTAssertEqual(s.onePercentLowFPS, 10, accuracy: 1e-9)
        XCTAssertEqual(s.avgFPS, 1000 * 100 / 1090, accuracy: 1e-6)
        XCTAssertEqual(s.percentile(50), 10, accuracy: 1e-9)
    }

    func testThermalPolicy() {
        XCTAssertFalse(ThermalPolicy.forState(0, userDetectEvery: 2).paused)
        XCTAssertEqual(ThermalPolicy.forState(2, userDetectEvery: 2).maxFPS, 15)
        XCTAssertTrue(ThermalPolicy.forState(3, userDetectEvery: 2).paused)
    }
}
